#!/usr/bin/env python3
"""Round 95b tiles (28 September): livestock density as relief (glw_relief.py), the World's Worst Plastic Polluters (plastic_polluters.py), skin farms added to fur_farms.py, and ocean acidification, heatwaves and bleaching, shipping and cumulative impacts (oceans_more.py). Upload to the culprits-tiles-more repo's patches folder. Safe to run twice."""
import base64, os, pathlib, sys
FILES = {
    'scripts/glw_relief.py': """""",
    'scripts/plastic_polluters.py': """""",
    'scripts/fur_farms.py': """""",
    'scripts/oceans_more.py': """""",
}
if not os.path.isdir("scripts"):
    sys.exit("Run this from the culprits-tiles-more folder.")
n = 0
for name, b in FILES.items():
    p, data = pathlib.Path(name), base64.b64decode(b)
    if p.exists() and p.read_bytes() == data:
        continue
    p.write_bytes(data); n += 1; print("written:", name)
print(f"{n} file(s) changed" if n else "Already applied. Nothing changed.")
